-- Ülke rozetleri (country badges), yalnızca ekleme (additive). EU prod (pubpfuoymdlgrdevedxk) üzerinde 2026-10-19 tarihinde onayla çalıştırıldı; tekrar çalıştırmak güvenli.
-- Üretildi: src/build-sql.mjs, kaynak countries.json. 245 ürün, hepsi 250 DesCoin.
BEGIN;

-- 1) Yeni sütunlar (nullable, mevcut satırlara dokunmaz)
ALTER TABLE public.shop_items ADD COLUMN IF NOT EXISTS country_code TEXT;
ALTER TABLE public.shop_items ADD COLUMN IF NOT EXISTS country_region TEXT;
ALTER TABLE public.shop_items ADD COLUMN IF NOT EXISTS country_kind TEXT;
CREATE UNIQUE INDEX IF NOT EXISTS shop_items_country_code_uniq ON public.shop_items(country_code) WHERE category = 'countries';
ALTER TABLE public.users ADD COLUMN IF NOT EXISTS equipped_country_id UUID REFERENCES public.shop_items(id) ON DELETE SET NULL;

-- 2) Kategori kısıtına 'countries' eklenir (mevcut 15 değer korunur)
ALTER TABLE public.shop_items DROP CONSTRAINT IF EXISTS shop_items_category_check;
ALTER TABLE public.shop_items ADD CONSTRAINT shop_items_category_check CHECK (category IN (
  'banner','avatar_frame','profile_background','theme','profile_badge','profile_title','name_effect',
  'avatar_effect','chat_bubble','presence_flare','profile_aura','sound_pack','typing_flare','reaction_burst',
  'call_overlay','countries'));

-- 3) Ürünler (sku benzersiz; tekrar çalıştırmak güvenli)
ON CONFLICT (sku) DO NOTHING;

-- 4) Ücretsiz ülke hakkı (unvan için DesCoin ödeyenler, Demir onayı 19.10.2026). Bakiye değil, envanter kredisi.
ALTER TABLE public.user_inventory DROP CONSTRAINT IF EXISTS user_inventory_acquired_via_check;
ALTER TABLE public.user_inventory ADD CONSTRAINT user_inventory_acquired_via_check
  CHECK (acquired_via IN ('purchase','gift','voucher'));
CREATE TABLE IF NOT EXISTS public.shop_vouchers (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,
  category TEXT NOT NULL CHECK (category IN ('countries')),
  reason TEXT NOT NULL,
  granted_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  redeemed_at TIMESTAMPTZ,
  redeemed_item_id UUID REFERENCES public.shop_items(id) ON DELETE SET NULL,
  UNIQUE (user_id, category, reason)
);
ALTER TABLE public.shop_vouchers ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.shop_vouchers FROM anon, authenticated;
CREATE INDEX IF NOT EXISTS shop_vouchers_open_idx ON public.shop_vouchers(user_id) WHERE redeemed_at IS NULL;

-- Ürünler PASİF eklenir (active=false); satış 05-activate-countries.sql ile açılır.
-- Kontrol: 245 olmalı
SELECT count(*) AS countries_total, count(*) FILTER (WHERE active) AS countries_active FROM public.shop_items WHERE category = 'countries';
COMMIT;
